  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import {
  7 |   TitleBar,
  8 |   Playlist,
  9 |   PlayerControls,
 10 |   ProgressBar,
 11 |   StatusBar,
 12 |   DriveBrowser,
 13 |   AudioVisualizer,
 14 | } from "./components";
 15 | import type { Track } from "./types";
 16 | 
 17 | function App() {
 18 |   const {
 19 |     state,
 20 |     play,
 21 |     pause,
 22 |     next,
 23 |     prev,
 24 |     seek,
 25 |     setVolume,
 26 |     addTrack,
 27 |     toggleShuffle,
 28 |     reorderPlaylist,
 29 |     toggleFavorite,
 30 |     audioRef,
 31 |   } = usePlayerWithAudio([]);
 32 | 
 33 |   const { processFiles } = useMetadata();
 34 |   const {
 35 |     state: tauriState,
 36 |     openFilePicker,
 37 |     filePathToUrl,
 38 |     sendNotification,
 39 |     registerShortcuts,
 40 |   } = useTauri();
 41 | 
 42 |   const [isLoading, setIsLoading] = useState(false);
 43 |   const [showDrive, setShowDrive] = useState(false);
 44 |   const [isCompact, setIsCompact] = useState(false);
 45 | 
 46 |   const fileInputRef = useRef<HTMLInputElement>(null);
 47 | 
 48 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 49 |   useEffect(() => {
 50 |     const cleanup = registerShortcuts({
 51 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 52 |       MediaNextTrack: () => next(),
 53 |       MediaPrevTrack: () => prev(),
 54 |       MediaStop: () => pause(),
 55 |     });
 56 | 
 57 |     return () => {
 58 |       cleanup.then((fn) => fn());
 59 |     };
 60 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 61 | 
 62 |   // Media Session API (navegador)
 63 |   useEffect(() => {
 64 |     if (!("mediaSession" in navigator)) return;
 65 | 
 66 |     navigator.mediaSession.metadata = new MediaMetadata({
 67 |       title: state.currentTrack?.title ?? "Llama Player",
 68 |       artist: state.currentTrack?.artist ?? undefined,
 69 |       album: state.currentTrack?.album ?? undefined,
 70 |     });
 71 | 
 72 |     navigator.mediaSession.setActionHandler("play", () => play());
 73 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 74 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 75 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 76 |   }, [state.currentTrack, play, pause, next, prev]);
 77 | 
 78 |   // Notificação ao trocar de música
 79 |   useEffect(() => {
 80 |     if (state.currentTrack && state.isPlaying) {
 81 |       sendNotification(
 82 |         `▶ ${state.currentTrack.title}`,
 83 |         state.currentTrack.artist
 84 |           ? `Por ${state.currentTrack.artist}`
 85 |           : undefined
 86 |       );
 87 |     }
 88 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
 89 | 
 90 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
 91 | 
 92 |   const handleSelectTrack = (track: Track) => {
 93 |     play(track);
 94 |   };
 95 | 
 96 |   const handleOpenFile = async () => {
 97 |     if (tauriState.isTauri) {
 98 |       // Usa file picker nativo do Tauri
 99 |       setIsLoading(true);
100 |       try {
101 |         const paths = await openFilePicker();
102 |         if (!paths || paths.length === 0) return;
103 | 
104 |         // Converte paths para File objects (via fetch do asset protocol)
105 |         const tracks: Track[] = [];
106 |         for (const path of paths) {
107 |           const url = await filePathToUrl(path);
108 |           const name = path.split(/[/\\]/).pop() || path;
109 |           tracks.push({
110 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
111 |             title: name.replace(/\.[^/.]+$/, ""),
112 |             duration: 0,
113 |             src: url,
114 |           });
115 |         }
116 | 
117 |         for (const track of tracks) {
118 |           addTrack(track);
119 |         }
120 | 
121 |         if (!state.currentTrack && tracks.length > 0) {
122 |           play(tracks[0]);
123 |         }
124 |       } catch (err) {
125 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
126 |       } finally {
127 |         setIsLoading(false);
128 |       }
129 |     } else {
130 |       // Fallback: input file HTML
131 |       fileInputRef.current?.click();
132 |     }
133 |   };
134 | 
135 |   const handleFileChange = useCallback(
136 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
137 |       const files = e.target.files;
138 |       if (!files || files.length === 0) return;
139 | 
140 |       setIsLoading(true);
141 | 
142 |       try {
143 |         const fileArray = Array.from(files);
144 |         const tracks = await processFiles(fileArray);
145 | 
146 |         for (const track of tracks) {
147 |           addTrack(track);
148 |         }
149 | 
150 |         // If nothing is playing, start with the first track
151 |         if (!state.currentTrack && tracks.length > 0) {
152 |           play(tracks[0]);
153 |         }
154 |       } catch (err) {
155 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
156 |       } finally {
157 |         setIsLoading(false);
158 |       }
159 | 
160 |       // Reset input so the same file can be selected again
161 |       e.target.value = "";
162 |     },
163 |     [processFiles, addTrack, state.currentTrack, play]
164 |   );
165 | 
166 |   const handleDropFiles = useCallback(
167 |     async (files: FileList) => {
168 |       setIsLoading(true);
169 |       try {
170 |         const fileArray = Array.from(files);
171 |         const tracks = await processFiles(fileArray);
172 |         for (const track of tracks) {
173 |           addTrack(track);
174 |         }
175 |         if (!state.currentTrack && tracks.length > 0) {
176 |           play(tracks[0]);
177 |         }
178 |       } catch (err) {
179 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
180 |       } finally {
181 |         setIsLoading(false);
182 |       }
183 |     },
184 |     [processFiles, addTrack, state.currentTrack, play]
185 |   );
186 | 
187 |   const handleAddDriveTracks = useCallback(
188 |     (tracks: Track[]) => {
189 |       for (const track of tracks) {
190 |         addTrack(track);
191 |       }
192 |       if (!state.currentTrack && tracks.length > 0) {
193 |         play(tracks[0]);
194 |       }
195 |     },
196 |     [addTrack, state.currentTrack, play]
197 |   );
198 | 
199 |   return (
200 |     <div className="app">
201 |       <TitleBar />
202 | 
203 |       <main className="main-content">
204 |         <div className="toolbar">
205 |           <button
206 |             className="toolbar-btn"
207 |             onClick={handleOpenFile}
208 |             disabled={isLoading}
209 |             title="Abrir arquivo de áudio local"
210 |           >
211 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
212 |           </button>
213 |           <input
214 |             ref={fileInputRef}
215 |             type="file"
216 |             accept="audio/*"
217 |             multiple
218 |             style={{ display: "none" }}
219 |             onChange={handleFileChange}
220 |           />
221 |           <button
222 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
223 |             onClick={() => setShowDrive((v) => !v)}
224 |             title="Google Drive"
225 |           >
226 |             ☁️ Drive
227 |           </button>
228 |         </div>
229 | 
230 |         {showDrive && (
231 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
232 |         )}
233 | 
234 |         <Playlist
235 |           tracks={state.playlist}
236 |           currentTrackId={state.currentTrack?.id ?? null}
237 |           isPlaying={state.isPlaying}
238 |           onSelectTrack={handleSelectTrack}
239 |           onReorderPlaylist={reorderPlaylist}
240 |           onDropFiles={handleDropFiles}
241 |           onToggleFavorite={toggleFavorite}
242 |         />
243 | 
244 |         <PlayerControls
245 |           currentTrack={state.currentTrack}
246 |           currentTrackId={state.currentTrack?.id ?? null}
247 |           isPlaying={state.isPlaying}
248 |           isShuffled={state.isShuffled}
249 |           isCompact={isCompact}
250 |           onPlay={() => play()}
251 |           onPause={pause}
252 |           onNext={next}
253 |           onPrev={prev}
254 |           onToggleShuffle={toggleShuffle}
255 |           onToggleFavorite={toggleFavorite}
256 |           onToggleCompact={() => setIsCompact((v) => !v)}
257 |         />
258 | 
259 |         <AudioVisualizer
260 |           frequencyData={visualizer.frequencyData}
261 |           waveformData={visualizer.waveformData}
262 |           isActive={visualizer.isActive}
263 |         />
264 | 
265 |         <ProgressBar
266 |           currentTime={state.currentTime}
267 |           duration={state.duration}
268 |           onSeek={seek}
269 |         />
270 |       </main>
271 | 
272 |       <StatusBar
273 |         isPlaying={state.isPlaying}
274 |         volume={state.volume}
275 |         onVolumeChange={setVolume}
276 |       />
277 |     </div>
278 |   );
279 | }
280 | 
281 | export default App;
282 |
